def lang_for(country_lang):
    return country_lang if country_lang in L else "en"

def build(name, lang, hook_kind, email_policy):
    """-> dict(local={...}, en={...}). hook_kind: pdf | none | gen"""
    out = {}
    for tag, lg in (("local", lang_for(lang)), ("en", "en")):
        t = L[lg]; hook = t["hook_" + hook_kind]
        fill = dict(name=name, hi=t["hi"], hook=hook, sig=t["sig"], stop=t["stop"])
        e = {"lang": lg, "subject": t["subj"].format(**fill), "email": t["body"].format(**fill), "dm": t["dm"].format(hook=hook), "offer": t["offer"]}
        if email_policy == "blocked": e["email"] = ""; e["subject"] = ""
        out[tag] = e
    return out
